var res = new List<object>();
foreach (Document d in app.Documents)
{
    if (d.IsFamilyDocument) continue;
    var locs = new List<object>();
    foreach (ProjectLocation pl in d.ProjectLocations)
    {
        ProjectPosition pp = null;
        try { pp = pl.GetProjectPosition(XYZ.Zero); } catch {}
        locs.Add(new {
            name = pl.Name,
            id = pl.Id.IntegerValue,
            isActive = d.ActiveProjectLocation.Id == pl.Id,
            ew_m = pp == null ? (double?)null : Math.Round(pp.EastWest*0.3048,4),
            ns_m = pp == null ? (double?)null : Math.Round(pp.NorthSouth*0.3048,4),
            elev_m = pp == null ? (double?)null : Math.Round(pp.Elevation*0.3048,4),
            angle_deg = pp == null ? (double?)null : Math.Round(pp.Angle*180/Math.PI,6)
        });
    }
    var bps = new FilteredElementCollector(d).OfClass(typeof(BasePoint)).Cast<BasePoint>()
        .Select(b => new {
            survey = b.IsShared,
            pos_m = new[]{Math.Round(b.Position.X*0.3048,4),Math.Round(b.Position.Y*0.3048,4),Math.Round(b.Position.Z*0.3048,4)},
            shared_m = new[]{Math.Round(b.SharedPosition.X*0.3048,4),Math.Round(b.SharedPosition.Y*0.3048,4),Math.Round(b.SharedPosition.Z*0.3048,4)},
            pinned = b.Pinned, clipped = b.Clipped
        }).ToList();
    var links = new FilteredElementCollector(d).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>()
        .Select(li => {
            var t = li.GetTotalTransform();
            var lt = d.GetElement(li.GetTypeId()) as RevitLinkType;
            string attach = null; try { attach = lt.AttachmentType.ToString(); } catch {}
            return new {
                name = li.Name,
                pinned = li.Pinned,
                attachment = attach,
                origin_m = new[]{Math.Round(t.Origin.X*0.3048,4),Math.Round(t.Origin.Y*0.3048,4),Math.Round(t.Origin.Z*0.3048,4)},
                rot_deg = Math.Round(Math.Atan2(t.BasisX.Y,t.BasisX.X)*180/Math.PI,6),
                sharedSite = li.LookupParameter("Shared Site")?.AsValueString()
            };
        }).ToList();
    res.Add(new {
        title = d.Title,
        path = d.PathName,
        isLinked = d.IsLinked,
        isWorkshared = d.IsWorkshared,
        locations = locs,
        basePoints = bps,
        links = links
    });
}
return res;
